/**
 * Plant catalog — Gardyn's published facts (light zone, first-harvest window,
 * care level, yield) plus rule-derived fields, generated by
 * scripts/plants/build-catalog.py into data/catalog.json. Provenance and the
 * cross-check against My Pod Planner live in knowledge/plants/.
 */
import { z } from 'zod'
import raw from './catalog.json'
import { defaultTolerance } from './tolerance'

export const Zone = z.enum(['high', 'medium', 'low'])
export type Zone = z.infer<typeof Zone>

export const Category = z.enum(['fruiting', 'vegetable', 'legume', 'flower', 'herb', 'green', 'lettuce'])
export type Category = z.infer<typeof Category>

/** Gardyn's succession-planting groups. */
export const Succession = z.enum(['fast-greens', 'long-greens-herbs', 'fast-fruiting', 'long-fruiting', 'flowers'])
export type Succession = z.infer<typeof Succession>

export const Plant = z.object({
  id: z.string(),
  name: z.string(),
  category: Category,
  zone: Zone,
  /** First harvest window in months after starting the yCube. */
  harvestMonths: z.tuple([z.number().int(), z.number().int()]),
  /** True when Gardyn publishes no window and the category median is used. */
  harvestEstimated: z.boolean(),
  careLevel: z.enum(['beginner', 'intermediate', 'expert']).nullable(),
  yield: z.enum(['light', 'generous', 'bountiful']).nullable(),
  succession: Succession,
  successionInferred: z.boolean(),
  /** 'large' plants shade neighbours; the planner spaces them apart. */
  size: z.enum(['large', 'normal']),
  /** Gardyn's explicit exception: cucumbers start bottom-centre and climb into the light. */
  placement: z.enum(['bottomCenter']).nullable(),
  gardynHandle: z.string().nullable(),
  inStore: z.boolean(),
  /** Added on this unit by a person or an agent (#130); built-in Gardyn plants are read-only. */
  custom: z.boolean().default(false),
  /** Zones beyond its ideal where it still does acceptably, cheapest first, each with its cost to the planner (src/plants/tolerance.ts). */
  tolerates: z.array(z.object({ zone: Zone, cost: z.number().int().min(1) })),
})
export type Plant = z.infer<typeof Plant>

const Days = z.tuple([z.number().int(), z.number().int()])

/** Sprouts to keep per yCube after thinning, or 'all' for a plant Gardyn says not to thin. */
export const ThinTo = z.union([z.number().int().min(1), z.literal('all')])
export type ThinTo = z.infer<typeof ThinTo>

/** A plant's page in Gardyn's help centre, as facts (scripts/plants/gardyn-help-plants.txt), with the thinning article's count. */
const Facts = z.object({
  thinTo: ThinTo.nullable(),
  article: z.string().optional(),
  latinName: z.string().nullable().optional(),
  /** Days to maturity; for fruiting plants it runs about a month ahead of the store's first harvest. */
  maturityDays: Days.nullable().optional(),
  /** Grown height in feet as Gardyn labels it: "<1", "1", "2-3", "1+". */
  heightFt: z.string().nullable().optional(),
  tempF: Days.nullable().optional(),
  /** When the seedlings take the full dose of plant food: true leaves or 1/2-inch roots, or roots only. */
  fullDose: z.enum(['leavesOrRoots', 'roots']).optional(),
})

const Catalog = z.object({
  version: z.literal(1),
  sources: z.record(z.string(), z.string()),
  categorySproutMedians: z.record(z.string(), Days),
  sproutDays: z.record(z.string(), Days),
  facts: z.record(z.string(), Facts),
  plants: z.array(Plant.omit({ tolerates: true })),
})

const catalog = Catalog.parse(raw)

/** Gardyn's plants, each with the zone tolerance its category earns. */
export const PLANTS: readonly Plant[] = catalog.plants.map(p => ({ ...p, tolerates: defaultTolerance(p) }))
export const CATALOG_SOURCES = catalog.sources

/** Days from sowing to the first sprout, [from, to]; `estimated` when it is the category's median because no source gives one for the plant. */
export interface SproutWindow { days: [number, number], estimated: boolean }

/** A plant's sprouting window from Gardyn's Plant Book, its help centre page or Iowa State's germination table, else its category's median; null for a category none has a plant in. */
export function sproutWindow(p: Pick<Plant, 'id' | 'category'>): SproutWindow | null {
  const own = catalog.sproutDays[p.id]
  if (own) return { days: own, estimated: false }
  const median = catalog.categorySproutMedians[p.category]
  return median ? { days: median, estimated: true } : null
}

/** A plant's facts from its help centre page; `thinTo` falls back to Gardyn's rule for its kind, flagged `thinEstimated`. */
export interface PlantFacts {
  thinTo: ThinTo
  thinEstimated: boolean
  /** help.mygardyn.com/en/articles/<article>; null for a plant with no page. */
  article: string | null
  latinName: string | null
  maturityDays: [number, number] | null
  heightFt: string | null
  tempF: [number, number] | null
  fullDose: 'leavesOrRoots' | 'roots' | null
}

/** Gardyn's thinning rule by kind: one for greens, lettuces, vegetables, fruiting plants and large flowers; three for herbs and small flowers. */
export function thinRule(p: Pick<Plant, 'category' | 'size'>): number {
  return p.category === 'herb' || (p.category === 'flower' && p.size !== 'large') ? 3 : 1
}

export function plantFacts(p: Pick<Plant, 'id' | 'category' | 'size'>): PlantFacts {
  const f = catalog.facts[p.id]
  return {
    thinTo: f?.thinTo ?? thinRule(p),
    thinEstimated: f?.thinTo == null,
    article: f?.article ?? null,
    latinName: f?.latinName ?? null,
    maturityDays: f?.maturityDays ?? null,
    heightFt: f?.heightFt ?? null,
    tempF: f?.tempF ?? null,
    fullDose: f?.fullDose ?? null,
  }
}

export interface PlantFilter {
  q?: string
  category?: Category
  zone?: Zone
  inStore?: boolean
  careLevel?: 'beginner' | 'intermediate' | 'expert'
  custom?: boolean
}

/** The catalog a request plans with: the built-in plants, then the unit's custom ones. */
export interface Catalog {
  plants: readonly Plant[]
  get(id: string): Plant | undefined
  /** Case/punctuation-insensitive lookup by id or name (for free-text pod names). */
  find(query: string): Plant | undefined
  search(f?: PlantFilter): Plant[]
}

const squash = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '')

export function makeCatalog(custom: readonly Plant[] = []): Catalog {
  const plants = [...PLANTS, ...custom]
  const byId = new Map(plants.map(p => [p.id, p]))
  return {
    plants,
    get: id => byId.get(id),
    find: query => byId.get(query) ?? plants.find(p => squash(p.name) === squash(query)),
    search: (f = {}) => {
      const q = f.q?.toLowerCase().trim()
      return plants.filter(p =>
        (!q || p.name.toLowerCase().includes(q) || p.id.includes(q))
        && (!f.category || p.category === f.category)
        && (!f.zone || p.zone === f.zone)
        && (f.inStore === undefined || p.inStore === f.inStore)
        && (!f.careLevel || p.careLevel === f.careLevel)
        && (f.custom === undefined || p.custom === f.custom))
    },
  }
}

/** Gardyn's plants only. */
export const BUILTIN = makeCatalog()

export function getPlant(id: string): Plant | undefined {
  return BUILTIN.get(id)
}

/** Case/punctuation-insensitive lookup by id or name (for free-text pod names). */
export function findPlant(query: string): Plant | undefined {
  return BUILTIN.find(query)
}

export function searchPlants(f: PlantFilter = {}): Plant[] {
  return BUILTIN.search(f)
}

/**
 * Gardyn's succession table: "start the next yCube about every…", as days
 * after the previous plant reaches harvest-ready maturity (greens/herbs) or
 * after reliable harvesting begins (fruiting). Midpoint of Gardyn's range.
 * Flowers: "as flowering declines" — no fixed cadence.
 */
export const SUCCESSION_GAP_DAYS: Record<Succession, number | null> = {
  'fast-greens': 10, // ~1–2 weeks
  'long-greens-herbs': 21, // 2–4 weeks
  'fast-fruiting': 31, // 3–6 weeks
  'long-fruiting': 56, // 6–10+ weeks
  'flowers': null,
}
